// Helper function to list available rotated log files via SSH
function list_rotated_logs($log_type, $username) {
  global $bots_ssh_host, $bots_ssh_username, $bots_ssh_password;
  try {
    $connection = SSHConnectionManager::getConnection($bots_ssh_host, $bots_ssh_username, $bots_ssh_password);
    $logDir = "/home/botofthespecter/logs/logs/$log_type";
    $baseFileName = "$username.txt";
    // List all files matching the pattern username.txt*
    $listCommand = "ls -1 " . escapeshellarg("$logDir/$baseFileName") . "* 2>/dev/null || echo ''";
    $result = SSHConnectionManager::executeCommandNoMarker($connection, $listCommand);
    if (trim($result) === '') {
      return [];
    }
    $files = explode("\n", trim($result));
    $rotatedLogs = [];
    foreach ($files as $file) {
      if (empty($file)) continue;
      $fileName = basename($file);
      // Get modification date for this file
      $dateCommand = "stat -c '%y' " . escapeshellarg($file) . " 2>/dev/null || date -r " . escapeshellarg($file) . " '+%Y-%m-%d %H:%M:%S' 2>/dev/null";
      $dateResult = SSHConnectionManager::executeCommandNoMarker($connection, $dateCommand);
      $fileDate = 'Unknown';
      if (!empty(trim($dateResult))) {
        // Extract just the date part (YYYY-MM-DD)
        if (preg_match('/(\d{4}-\d{2}-\d{2})/', $dateResult, $dateMatches)) {
          $fileDate = $dateMatches[1];
        }
      }
      // Match username.txt or username.txt.N
      if ($fileName === $baseFileName) {
        $rotatedLogs[] = ['file' => $fileName, 'rotation' => 0, 'label' => "Current ($fileDate)"];
      } elseif (preg_match('/^' . preg_quote($baseFileName, '/') . '\.(\d+)$/', $fileName, $matches)) {
        $rotation = (int)$matches[1];
        $rotatedLogs[] = ['file' => $fileName, 'rotation' => $rotation, 'label' => $fileDate];
      }
    }
    // Sort by rotation number (0 first, then 1, 2, 3...)
    usort($rotatedLogs, function($a, $b) {
      return $a['rotation'] - $b['rotation'];
    });
    return $rotatedLogs;
  } catch (Exception $e) {
    return [];
  }
}

// Helper function to read log file via SSH
function read_log_file($file_path) {
  global $bots_ssh_host, $bots_ssh_username, $bots_ssh_password;
  try {
    $connection = SSHConnectionManager::getConnection($bots_ssh_host, $bots_ssh_username, $bots_ssh_password);
    $checkCommand = "test -f " . escapeshellarg($file_path) . " && echo '1' || echo '0'";
    $checkResult = SSHConnectionManager::executeCommandNoMarker($connection, $checkCommand);
    if (trim($checkResult) !== '1') {
      $dirname = dirname($file_path);
      $dirCheckCommand = "test -d " . escapeshellarg($dirname) . " && echo '1' || echo '0'";
      $dirCheckResult = SSHConnectionManager::executeCommandNoMarker($connection, $dirCheckCommand);
      if (trim($dirCheckResult) !== '1') {
        return ['error' => 'Log directory not found'];
      }
      return ['error' => 'Log file not found'];
    }
    // Read the entire file using the no-marker function to avoid appended exit markers
    $readCommand = "cat " . escapeshellarg($file_path);
    $logContent = SSHConnectionManager::executeCommandNoMarker($connection, $readCommand, 10);
    if ($logContent === false) {
      return ['error' => 'Failed to read log file'];
    }
    $lines = explode("\n", $logContent);
    $linesTotal = count($lines);
    return [
      'linesTotal' => $linesTotal,
      'logContent' => $logContent
    ];
  } catch (Exception $e) {
    error_log('beta logs: SSH connection failed: ' . $e->getMessage());
    return ['error' => 'Could not read this log right now. Please try again.'];
  }
}

// Helper function to highlight log dates in a string and add <br> at end of each line
function highlight_log_dates($text) {
  $dateStyle = 'style="color: #e67e22; font-weight: bold;"';
  $infoStyle = 'style="color: #3498db; font-weight: bold;"';
  $errorStyle = 'style="color: #e74c3c; font-weight: bold;"';
  $warningStyle = 'style="color: #f39c12; font-weight: bold;"';
  $debugStyle = 'style="color: #95a5a6; font-weight: bold;"';
  $escaped = htmlspecialchars($text);
  $lines = explode("\n", $escaped);
  foreach ($lines as &$line) {
    // Highlight date
    $line = preg_replace(
      '/(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})/',
      '<span ' . $dateStyle . '>$1</span>',
      $line
    );
    // Highlight log levels
    $line = preg_replace(
      '/ - (info) - /',
      ' - <span ' . $infoStyle . '>$1</span> - ',
      $line
    );
    $line = preg_replace(
      '/ - (error) - /',
      ' - <span ' . $errorStyle . '>$1</span> - ',
      $line
    );
    $line = preg_replace(
      '/ - (warning) - /',
      ' - <span ' . $warningStyle . '>$1</span> - ',
      $line
    );
    $line = preg_replace(
      '/ - (debug) - /',
      ' - <span ' . $debugStyle . '>$1</span> - ',
      $line
    );
  }
  return implode("<br>", $lines);
}

