function beta_cm_fail(string $msg, int $code = 400): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
function beta_cm_out(array $body): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    header('Content-Type: application/json'); header('Cache-Control: no-store');
    echo json_encode($body); exit();
}

